extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var label := find_by_name(main, "CrystalLabel") as Label
	var crystal := find_by_name(main, "Crystal") as Node3D
	if not check("nodes", label != null and crystal != null, "CrystalLabel e Crystal devono essere presenti"):
		return
	var active_cam := main.get_viewport().get_camera_3d()
	if not check("cam", active_cam != null, "Ci deve essere una telecamera attiva"):
		return
	check("frustum_code", count_in_code("res://main.gd", "is_position_in_frustum") > 0, "La funzione _update_crystal_label_position deve usare il metodo is_position_in_frustum")
	crystal.global_position = Vector3(100.0, 0.0, -5.0)
	await wait_frames(2)
	check("label_hidden_frustum", not label.visible, "Quando il cristallo si trova fuori dal frustum della telecamera, CrystalLabel deve essere nascosta")

